import{_ as s,C as n,o,c,j as t,a,b as d,w as i,E as l,a3 as u,a2 as h}from"./chunks/framework.BdoLZDHZ.js";const w=JSON.parse('{"title":"Authentication and authorization","description":"","frontmatter":{},"headers":[],"relativePath":"security/walkthrough-auth.md","filePath":"security/walkthrough-auth.md"}'),p={name:"security/walkthrough-auth.md"};function g(m,e,k,b,y,f){const r=n("Mermaid");return o(),c("div",null,[e[1]||(e[1]=t("h1",{id:"authentication-and-authorization",tabindex:"-1"},[a("Authentication and authorization "),t("a",{class:"header-anchor",href:"#authentication-and-authorization","aria-label":'Permalink to "Authentication and authorization"'},"​")],-1)),e[2]||(e[2]=t("p",null,"KAOS joins the agent actor and user subject planes at Envoy Gateway, then sends the request to the gateway-external OPA policy decision point (PDP).",-1)),e[3]||(e[3]=t("h2",{id:"request-path",tabindex:"-1"},[a("Request path "),t("a",{class:"header-anchor",href:"#request-path","aria-label":'Permalink to "Request path"'},"​")],-1)),(o(),d(u,null,{default:i(()=>[l(r,{id:"mermaid-9",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20C%5BAgent%20request%5D%20--%3E%7CAuthorization%20%2B%20x-agent-authorization%7C%20G%5BEnvoy%20Gateway%5D%0A%20%20%20%20G%20--%3E%7Cagent%20and%20user%20JWT%20providers%7C%20J%5BJWT%20verification%5D%0A%20%20%20%20G%20--%3E%7CgRPC%20ext_authz%7C%20P%5Bkaos-pdp%20%2F%20OPA%5D%0A%20%20%20%20D%5Bpolicy.rego%20%2B%20data.json%5D%20--%3E%20P%0A%20%20%20%20P%20--%3E%7Callow%20or%20deny%7C%20G%0A%20%20%20%20G%20--%3E%7Callowed%20request%7C%20R%5BTarget%20resource%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=h('<p>The gateway <code>jwt_authn</code> configuration contains two independent providers when both planes are configured:</p><ul><li><code>agent</code> reads <code>x-agent-authorization</code>, verifies the selected actor issuer, and requires audience <code>kaos-gateway</code>.</li><li><code>user</code> reads <code>Authorization</code> and verifies the configured Keycloak issuer and audience.</li></ul><p>The gateway invokes OPA through the Envoy gRPC <code>ext_authz</code> filter, and the <code>SecurityPolicy</code> sets <code>failOpen: false</code>; invalid identity, an explicit policy denial, or an unavailable PDP does not reach the workload.</p><h2 id="gateway-jwt-behavior" tabindex="-1">Gateway JWT behavior <a class="header-anchor" href="#gateway-jwt-behavior" aria-label="Permalink to &quot;Gateway JWT behavior&quot;">​</a></h2><p><code>security.agentAuth.gatewayJwtOptional</code> defaults to <code>true</code>, keeping gateway JWT processing non-blocking so agent-issuer tokens carried in <code>Authorization</code> can reach the PDP for autonomous self-subjecting. The PDP still verifies every required token and remains authoritative. Setting this value to <code>false</code> makes the gateway reject invalid tokens at the edge, but it also breaks autonomous agents because the user provider rejects their propagated agent-issuer self-subject token before the PDP runs. Set it to <code>false</code> only when no autonomous agents run; the value has no effect without the PDP.</p><h2 id="subject-required-authorization-model" tabindex="-1">Subject-required authorization model <a class="header-anchor" href="#subject-required-authorization-model" aria-label="Permalink to &quot;Subject-required authorization model&quot;">​</a></h2><p>Every protected request requires a verified subject on every hop:</p><ul><li>A user subject is a verified Keycloak token whose <code>sub</code> or <code>email</code>, and optional short-name <code>groups</code>, identify the user.</li><li>An autonomous Agent can self-subject with its own verified agent token only when <code>data.kaos.agents[id].autonomous</code> is <code>true</code>. A non-autonomous Agent cannot self-subject.</li></ul><p>Entry and internal movement use different grants:</p><ul><li>At entry, <code>Authorization</code> carries the user token and no actor token is present. An enforced <code>AccessGrant</code> in <code>data.kaos.user_grants</code> must cover the path-derived target for that user or one of their groups.</li><li>On an internal hop, <code>Authorization</code> carries the propagated subject and <code>x-agent-authorization</code> carries the calling Agent&#39;s token. The subject must remain valid, while <code>data.kaos.grants</code> determines whether that Agent may move to the target resource.</li></ul><p>This keeps user intent attached to the complete call chain while separating permission to enter the system from permission for each Agent to move inside it.</p><h2 id="keycloak-groups-claim-requirement" tabindex="-1">Keycloak groups claim requirement <a class="header-anchor" href="#keycloak-groups-claim-requirement" aria-label="Permalink to &quot;Keycloak groups claim requirement&quot;">​</a></h2><p>Group-based <code>AccessGrant</code>s require a Keycloak Group Membership protocol mapper that emits the <code>groups</code> claim in access tokens. Configure the mapper with access-token claims enabled and <code>full.path: false</code>; group subjects consequently use short names, such as <code>name: researchers</code>, rather than <code>/researchers</code>.</p><p>This mapper is a hard requirement: without the <code>groups</code> claim, group-based grants cannot match. The CLI provisions it automatically for the managed Keycloak preset, while bring-your-own-Keycloak deployments must configure it themselves.</p><h2 id="request-conventions" tabindex="-1">Request conventions <a class="header-anchor" href="#request-conventions" aria-label="Permalink to &quot;Request conventions&quot;">​</a></h2><p>The actor credential is:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">x-agent-authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;actor-jwt&gt;</span></span></code></pre></div><p>The subject credential is:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;subject-jwt&gt;</span></span></code></pre></div><p>At user entry the subject is a Keycloak token. During autonomous execution it is the autonomous Agent&#39;s own agent token. Internal calls propagate the subject unchanged and replace the actor token with the current calling Agent&#39;s token.</p><p>Protected resources use logical ids:</p><ul><li><code>kaos://agent/&lt;namespace&gt;/&lt;name&gt;</code></li><li><code>kaos://mcpserver/&lt;namespace&gt;/&lt;name&gt;</code></li><li><code>kaos://modelapi/&lt;namespace&gt;/&lt;name&gt;</code></li><li><code>kaos://memorystore/&lt;namespace&gt;/&lt;name&gt;</code></li></ul><p>OPA derives the target from the operator-owned route path <code>/&lt;namespace&gt;/&lt;route-kind&gt;/&lt;name&gt;/...</code>; route kind <code>mcp</code> maps to <code>mcpserver</code>. Although routes stamp <code>x-kaos-target-resource</code> for the forwarded request, route header modifiers run after external authorization. The PDP therefore does not trust an inbound target-resource header.</p><h2 id="published-policy-contract" tabindex="-1">Published policy contract <a class="header-anchor" href="#published-policy-contract" aria-label="Permalink to &quot;Published policy contract&quot;">​</a></h2><p>OPA reads the following stable fields from <code>data.kaos</code>:</p><ul><li><code>data.kaos.grants</code>: logical actor id to allowed target-resource ids.</li><li><code>data.kaos.user_grants</code>: <code>user:&lt;sub-or-email&gt;</code> or <code>group:&lt;name&gt;</code> to allowed entry-resource ids.</li><li><code>data.kaos.jwks</code>: exact actor-token issuer to JWKS.</li><li><code>data.kaos.agents</code>: logical actor id to issuer-specific token subject and autonomous status.</li></ul><p>The shipped policy verifies subject and actor tokens, resolves agent subjects through <code>data.kaos.agents</code>, derives the target resource from the request path, and applies the entry or internal grant check.</p><h2 id="does-not-support" tabindex="-1">Does not support <a class="header-anchor" href="#does-not-support" aria-label="Permalink to &quot;Does not support&quot;">​</a></h2><ul><li>Per-user downstream authorization is not supported. User grants gate entry; internal hops require a valid propagated subject but authorize movement with the calling Agent&#39;s grants.</li><li>Policy and grant changes, including revocations, can take about 90 seconds to pass through reconciliation, the ConfigMap volume, OPA file watching, and gateway configuration.</li><li>ServiceAccount JWKS is discovered and cached at operator startup. Restart the operator after ServiceAccount signing-key rotation.</li><li>Token signature verification supports RS256 only.</li></ul><p>The default decision is deny. Missing or invalid subjects, invalid actors on internal hops, unknown targets, and absent grants are denied.</p>',30))])}const A=s(p,[["render",g]]);export{w as __pageData,A as default};
